mapper.select:
SELECT (t.occurred_at AT TIME ZONE 'Asia/Shanghai')::date AS biz_date, coalesce(t.pay_point, '(未指定)') AS pay_point, (t.method = '现金') AS cash, count(*) AS txn_count, coalesce(sum(t.amount) FILTER (WHERE t.direction = 'I'), 0) AS in_amount, coalesce(sum(t.amount) FILTER (WHERE t.direction = 'O'), 0) AS out_amount FROM deposit_txn t WHERE t.direction IN ('I', 'O') AND t.occurred_at >= #{fromTs} AND t.occurred_at < #{toTs}
AND EXISTS (SELECT 1 FROM deposit d WHERE d.id = t.deposit_id AND d.community_id = #{communityId})
GROUP BY 1, 2, 3 ORDER BY 1, 2, 3
